<?php
require_once 'conexion.php';function fallo($m,$s=422){http_response_code($s);exit('<div class="notification is-danger">'.htmlspecialchars($m,ENT_QUOTES,'UTF-8').'</div>');}
if(($_SERVER['REQUEST_METHOD']??'')!=='POST'){http_response_code(405);exit('Método no permitido.');}
$id=filter_var($_POST['id_medicamento']??'0',FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);$cat=filter_var($_POST['id_categoria']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$nombre=trim($_POST['nombre']??'');$pres=($_POST['id_presentacion']??'')===''?null:filter_var($_POST['id_presentacion'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$conc=trim($_POST['concentracion']??'');$venta=trim($_POST['precio_venta']??'');$costo=trim($_POST['precio_costo']??'');$iva=trim($_POST['iva_porcentaje']??'');$barra=trim($_POST['codigo_barras']??'');$alm=trim($_POST['condicion_almacenamiento']??'');$receta=isset($_POST['requiere_receta'])?1:0;
if($id===false||$cat===false)fallo('Seleccione una categoría válida.');if($pres===false)fallo('Seleccione una presentación válida.');if($nombre==='')fallo('El nombre es obligatorio.');if(!preg_match('/^\d{1,10}(\.\d{1,2})?$/D',$venta)||!preg_match('/^\d{1,10}(\.\d{1,2})?$/D',$costo))fallo('Los precios deben ser números positivos con hasta dos decimales.');if(!is_numeric($iva)||(float)$iva<0||(float)$iva>100)fallo('El IVA debe estar entre 0 y 100.');
try{$s=$pdo->prepare('SELECT id_categoria FROM dbo.categoria WHERE id_categoria=?');$s->execute([$cat]);if(!$s->fetch())fallo('La categoría seleccionada no existe.');if($pres!==null){$s=$pdo->prepare('SELECT id_presentacion FROM dbo.presentacion WHERE id_presentacion=?');$s->execute([$pres]);if(!$s->fetch())fallo('La presentación seleccionada no existe.');}if($id>0){$s=$pdo->prepare('UPDATE dbo.medicamento SET id_categoria=?,nombre=?,id_presentacion=?,concentracion=?,precio_venta=?,requiere_receta=?,condicion_almacenamiento=?,codigo_barras=?,precio_costo=?,iva_porcentaje=? WHERE id_medicamento=?');$s->execute([$cat,$nombre,$pres,$conc?:null,$venta,$receta,$alm?:null,$barra?:null,$costo,$iva,$id]);if($s->rowCount()===0){$s=$pdo->prepare('SELECT id_medicamento FROM dbo.medicamento WHERE id_medicamento=?');$s->execute([$id]);if(!$s->fetch())fallo('El medicamento ya no existe.',404);}}else{$s=$pdo->prepare('INSERT INTO dbo.medicamento (id_categoria,nombre,id_presentacion,concentracion,precio_venta,requiere_receta,condicion_almacenamiento,codigo_barras,precio_costo,iva_porcentaje) VALUES (?,?,?,?,?,?,?,?,?,?)');$s->execute([$cat,$nombre,$pres,$conc?:null,$venta,$receta,$alm?:null,$barra?:null,$costo,$iva]);}header('HX-Trigger: medicamentoGuardado');echo '<div class="notification is-success">Medicamento guardado correctamente.</div>';}catch(PDOException $e){error_log($e->getMessage());if(in_array((int)($e->errorInfo[1]??0),[2601,2627],true))fallo('El código de barras ya está registrado.',409);fallo('No se pudo guardar. Verifique los datos y que las columnas coincidan con la base de datos.',500);}
